```css
* {
  box-sizing: border-box;
}
.card {
  width: 100%;
  max-width: 360px;
  margin: 18px auto;
  padding: 14px;
  border: 2px solid #456;
}
.card img {
  display: block;
  max-width: 100%;
  height: auto;
}
.badge {
  display: inline-block;
  padding: 3px 7px;
  background: #e1f3e9;
  border-radius: 6px;
