@media (prefers-reduced-motion: reduce) { .bar { /* TODO: immediate final state */ } }

solution:
.bar { width: 100%; height: 18px; background: #287d5a; animation: fill 2s ease-out both; }
@keyframes fill { from { width: 0; } to { width: 100%; } }
@media (prefers-reduced-motion: reduce) { .bar { animation: none; width: 100%; } }

