Editing after undo creates a new branch.
```javascript
let versions = ["A", "B", "C"];
let cursor = 1;
versions = versions.slice(0, cursor + 1);
versions.push("D");
cursor = versions.length - 1;
console.log(versions, versions[cursor]);
```
The versions are A, B, D and the current text is D. slice excludes its end index, so cursor + 1 keeps the current version before appending.

starter:
function createHistory(initial) {
  // TODO: store versions and a cursor in this closure.
  return { current: () => initial, edit: text => initial, undo: () => initial, redo: () => initial };
}

solution:
function createHistory(initial) {
  let versions = [initial];
  let cursor = 0;
  const current = () => versions[cursor];
  return {
    current,
    edit(text) {
      if (text === current()) return current();
      versions = versions.slice(0, cursor + 1);
      versions.push(text); cursor += 1; return current();
    },
    undo() { cursor = Math.max(0, cursor - 1); return current(); },
    redo() { cursor = Math.min(versions.length - 1, cursor + 1); return current(); }
  };
}

