CREATE VIEW folder_paths AS
WITH RECURSIVE paths(id, path, depth) AS (
  SELECT id, name, 0 FROM folders WHERE parent_id IS NULL
  UNION ALL
  SELECT child.id, parent.path || '/' || child.name, parent.depth + 1
  FROM folders AS child JOIN paths AS parent ON child.parent_id = parent.id
)
