  // TODO: replay matching requests; reject conflicting key reuse.
  return {status: 201, id: 0, title};
}

solution:
function createOnce(cache, key, title) {
  if (cache.has(key)) {
    const saved = cache.get(key);
    return saved.title === title ? {...saved.result} : {status: 409};
  }
  const result = {status: 201, id: cache.size + 1, title};
  cache.set(key, {title, result});
  return {...result};
}

